import {
  formatEmail,
  formatFacebook,
  formatInstagram,
  formatNumber,
  formatOther,
  formatTelegram,
  formatTikTok,
  formatTwitter,
  formatYoutube,
  formatVk,
  formatDate,
  removeSpacesLeaveEnter,
  removeExtraSpaces,
  formatDateAndFormula,
} from './inputValidations';

export const inputUpdateValue = (value, field, data) => {
  return (
    // field.name === 'birth'
    field.name?.startsWith('birth')
      ? formatDate(value)
      : field.name === 'lastDelivery'
      ? formatDate(value, true)
      : field.name === 'opuDate'
      ? formatDate(value, true)
      : // : field.name === 'experience'
      // ? createOpuData(value)
      // Винагорода — опис, а не число: «від 1000 $, залежить від програми,
      // компенсація дороги». `formatNumber(value, 9999)` тут лишав самі цифри
      // й обрізав усе, що більше за 9999.
      field.name === 'reward'
      ? removeSpacesLeaveEnter(value)
      : field.name === 'ownKids'
      ? formatNumber(value, 10)
      : field.name === 'shoeSize'
      ? value.slice(0, 2)
      : field.name === 'clothingSize'
      ? value.slice(0, 50)
      : field.name === 'weight' ||
        field.name === 'weightWife' ||
        field.name === 'weightHusband' ||
        field.name === 'height' ||
        field.name === 'heightWife' ||
        field.name === 'heightHusband'
      ? formatNumber(value, 250)
      : field.name === 'telegram'
      ? formatTelegram(value)
      : field.name === 'facebook'
      ? formatFacebook(value)
      : field.name === 'vk'
      ? Array.isArray(value)
        ? value.map(item => formatVk(item))
        : formatVk(value)
      : field.name === 'instagram'
      ? formatInstagram(value)
      : field.name === 'email'
      ? formatEmail(value)
      : field.name === 'tiktok'
      ? formatTikTok(value)
      : field.name === 'twitter'
      ? formatTwitter(value)
      : field.name === 'youtube'
      ? formatYoutube(value)
      : field.name === 'other'
      ? formatOther(value)
      : field.name === 'experience'
      ? formatNumber(value, 16)
      : field.name?.startsWith('more')
      ? removeSpacesLeaveEnter(value)
      : field.name === 'getInTouch'
      ? formatDateAndFormula(value)
      : removeExtraSpaces(value)
  );
};
